  data.append(match[1],(match[2]||'').replaceAll('&quot;','\"').replaceAll('&amp;','&'));
}
const response=await fetch("'`${base}/books/${book.id}`,{method:'"'POST',body:data,headers:{origin:base},redirect:'manual'});
console.log('Finish POST:',response.status,'location:',response.headers.get('location'));
const updated=JSON.parse(await readFile('data/books.json','utf8'))[0];
console.log('Saved status:',updated.status,'finishedAt:',Boolean(updated.finishedAt));
const home=await (await fetch(base)).text();
console.log('Home finished section contains book:',home.includes('Finished books')&&home.includes(book.title));
